import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content
    if not content:
        return {}
    encoding = from_encoding
    if encoding is None:
        detection = chardet.detect(content)
        encoding = detection.get("encoding")
    if not encoding:
        raise ValueError("Unable to detect encoding for non-empty content")
    text = content.decode(encoding, errors="strict")
    normalized_bytes = text.encode(to_encoding, errors="strict")
    normalized_text = normalized_bytes.decode(to_encoding, errors="strict")
    return json.loads(normalized_text)

import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content_bytes = response.content
    if not content_bytes:
        return {}
    if from_encoding is None:
        detection = chardet.detect(content_bytes)
        encoding = detection.get("encoding")
        confidence = detection.get("confidence") or 0
        if not encoding or confidence == 0:
            raise ValueError("Unable to detect encoding for non-empty content")
        from_encoding = encoding
    text = content_bytes.decode(from_encoding, errors="strict")
    normalized_bytes = text.encode(to_encoding, errors="strict")
    normalized_text = normalized_bytes.decode(to_encoding, errors="strict")
    return json.loads(normalized_text)

import ast
import json
from collections import Counter
def task_func(file_pointer):
    data = json.load(file_pointer)
    key_counter = Counter()
    for item in data:
        d = None
        if isinstance(item, dict):
            d = item
        elif isinstance(item, str):
            try:
                evaluated = ast.literal_eval(item)
                if isinstance(evaluated, dict):
                    d = evaluated
            except (ValueError, SyntaxError):
                continue
        if isinstance(d, dict):
            key_counter.update(d.keys())
    return key_counter

